import "/home/ubuntu/spyfallua/node_modules/dotenv/config.js";
const base = "http://127.0.0.1:3000/api/game";
const run = `qa-ui-${Date.now().toString(36)}`;
const users = ["a", "b"].map(suffix => ({ id: `${run}-${suffix}`, h: { "content-type": "application/json", "x-preview-player": `${run}-${suffix}` } }));
async function req(user, path, method = "GET", data) {
  const response = await fetch(base + path, { method, headers: user.h, ...(data ? { body: JSON.stringify(data) } : {}) });
  const body = await response.json();
  if (!response.ok) throw new Error(`${response.status}: ${body.error}`);
  return body;
}
for (const user of users) await req(user, "/session");
const created = await req(users[0], "/rooms", "POST", { name: "Перевірка чату", maxPlayers: 3, spyCount: 1, durationMinutes: 5, allowRejoin: true, isPrivate: true, categories: [], mode: "spyfall" });
const code = created.room.code;
await req(users[1], `/rooms/${code}/join`, "POST", {});
await req(users[1], `/rooms/${code}/messages`, "POST", { text: "Командо, зв’язок перевірено." });
console.log(JSON.stringify({ code, run, ids: users.map(user => `preview:${user.h["x-preview-player"]}`) }));
NODE

